    }

    // Build intervals for bytes div
    #[derive(Clone, Debug)]
    struct Interval {
        start: u64,
        end: u64,
        class: String,
        // for sorting, we need size and index
        size: u64,
        index: usize,
        // kind for ordering priority: 0=ehdr,1=segment,2=phdr,3=shdr,4=section,5=subrange,6=ident,7=field
        // We'll define priority for outer first: smaller priority = outer
