    // magic
    intervals.push(Interval { start: 0, end: 4, class: "magic".to_string(), size: 4, index: 0, priority: 2 });
    // class
    intervals.push(Interval { start: 4, end: 5, class: "class".to_string(), size: 1, index: 0, priority: 2 });
    intervals.push(Interval { start: 5, end: 6, class: "data".to_string(), size: 1, index: 0, priority: 2 });
    intervals.push(Interval { start: 6, end: 7, class: "ver".to_string(), size: 1, index: 0, priority: 2 });
    intervals.push(Interval { start: 7, end: 8, class: "abi".to_string(), size: 1, index: 0, priority: 2 });
    intervals.push(Interval { start: 8, end: 9, class: "abi_ver".to_string(), size: 1, index: 0, priority: 2 });
    intervals.push(Interval { start: 9, end: 16, class: "pad".to_string(), size: 7, index: 0, priority: 2 });

    if is_64 {
        intervals.push(Interval { start: 16, end: 18, class: "e_type".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 18, end: 20, class: "e_machine".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 20, end: 24, class: "e_version".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 24, end: 32, class: "e_entry".to_string(), size: 8, index: 0, priority: 2 });
        intervals.push(Interval { start: 32, end: 40, class: "e_phoff".to_string(), size: 8, index: 0, priority: 2 });
        intervals.push(Interval { start: 40, end: 48, class: "e_shoff".to_string(), size: 8, index: 0, priority: 2 });
        intervals.push(Interval { start: 48, end: 52, class: "e_flags".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 52, end: 54, class: "e_ehsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 54, end: 56, class: "e_phentsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 56, end: 58, class: "e_phnum".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 58, end: 60, class: "e_shentsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 60, end: 62, class: "e_shnum".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 62, end: 64, class: "e_shstrndx".to_string(), size: 2, index: 0, priority: 2 });
    } else {
        intervals.push(Interval { start: 16, end: 18, class: "e_type".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 18, end: 20, class: "e_machine".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 20, end: 24, class: "e_version".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 24, end: 28, class: "e_entry".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 28, end: 32, class: "e_phoff".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 32, end: 36, class: "e_shoff".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 36, end: 40, class: "e_flags".to_string(), size: 4, index: 0, priority: 2 });
        intervals.push(Interval { start: 40, end: 42, class: "e_ehsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 42, end: 44, class: "e_phentsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 44, end: 46, class: "e_phnum".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 46, end: 48, class: "e_shentsize".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 48, end: 50, class: "e_shnum".to_string(), size: 2, index: 0, priority: 2 });
        intervals.push(Interval { start: 50, end: 52, class: "e_shstrndx".to_string(), size: 2, index: 0, priority: 2 });
    }

    // phdrs and their fields
    for ph in &phdrs {
        let start = ph.p_offset; // actually file offset for segment, but for phdr header its file offset is e_phoff + index*entsize
        // we already have start for phdr header via e_phoff
        let ph_start = e_phoff + (ph.index as u64 * e_phentsize as u64);
        let ph_end = ph_start + e_phentsize as u64;
        intervals.push(Interval { start: ph_start, end: ph_end, class: format!("bin_phdr{} phdr", ph.index), size: e_phentsize as u64, index: ph.index, priority: 3 });
        if is_64 {
            intervals.push(Interval { start: ph_start+0, end: ph_start+4, class: "p_type".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+4, end: ph_start+8, class: "p_flags".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+8, end: ph_start+16, class: "p_offset".to_string(), size: 8, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+16, end: ph_start+24, class: "p_vaddr".to_string(), size: 8, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+24, end: ph_start+32, class: "p_paddr".to_string(), size: 8, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+32, end: ph_start+40, class: "p_filesz".to_string(), size: 8, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+40, end: ph_start+48, class: "p_memsz".to_string(), size: 8, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+48, end: ph_start+56, class: "p_align".to_string(), size: 8, index: ph.index, priority: 4 });
        } else {
            intervals.push(Interval { start: ph_start+0, end: ph_start+4, class: "p_type".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+4, end: ph_start+8, class: "p_offset".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+8, end: ph_start+12, class: "p_vaddr".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+12, end: ph_start+16, class: "p_paddr".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+16, end: ph_start+20, class: "p_filesz".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+20, end: ph_start+24, class: "p_memsz".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+24, end: ph_start+28, class: "p_flags".to_string(), size: 4, index: ph.index, priority: 4 });
            intervals.push(Interval { start: ph_start+28, end: ph_start+32, class: "p_align".to_string(), size: 4, index: ph.index, priority: 4 });
        }
    }

    // shdrs and fields
    for sh in &shdrs {
        let sh_start = e_shoff + (sh.index as u64 * e_shentsize as u64);
        let sh_end = sh_start + e_shentsize as u64;
        intervals.push(Interval { start: sh_start, end: sh_end, class: format!("bin_shdr{} shdr", sh.index), size: e_shentsize as u64, index: sh.index, priority: 3 });
        if is_64 {
            intervals.push(Interval { start: sh_start+0, end: sh_start+4, class: "sh_name".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+4, end: sh_start+8, class: "sh_type".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+8, end: sh_start+16, class: "sh_flags".to_string(), size: 8, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+16, end: sh_start+24, class: "sh_addr".to_string(), size: 8, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+24, end: sh_start+32, class: "sh_offset".to_string(), size: 8, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+32, end: sh_start+40, class: "sh_size".to_string(), size: 8, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+40, end: sh_start+44, class: "sh_link".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+44, end: sh_start+48, class: "sh_info".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+48, end: sh_start+56, class: "sh_addralign".to_string(), size: 8, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+56, end: sh_start+64, class: "sh_entsize".to_string(), size: 8, index: sh.index, priority: 4 });
        } else {
            intervals.push(Interval { start: sh_start+0, end: sh_start+4, class: "sh_name".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+4, end: sh_start+8, class: "sh_type".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+8, end: sh_start+12, class: "sh_flags".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+12, end: sh_start+16, class: "sh_addr".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+16, end: sh_start+20, class: "sh_offset".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+20, end: sh_start+24, class: "sh_size".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+24, end: sh_start+28, class: "sh_link".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+28, end: sh_start+32, class: "sh_info".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+32, end: sh_start+36, class: "sh_addralign".to_string(), size: 4, index: sh.index, priority: 4 });
            intervals.push(Interval { start: sh_start+36, end: sh_start+40, class: "sh_entsize".to_string(), size: 4, index: sh.index, priority: 4 });
        }
    }

    // segments to display (filtered)
    let mut displayed_segments: Vec<Phdr> = Vec::new();
    for ph in &phdrs {
        if ph.p_offset !=0 && ph.p_filesz !=0 {
            displayed_segments.push(ph.clone());
            intervals.push(Interval { start: ph.p_offset, end: ph.p_offset+ph.p_filesz, class: format!("bin_segment{} segment", ph.index), size: ph.p_filesz, index: ph.index, priority: 1 });
        }
    }

    // sections to display
    let mut displayed_sections: Vec<Shdr> = Vec::new();
    for sh in &shdrs {
        if sh.sh_type !=0 && sh.sh_type !=8 && sh.sh_size>0 {
            // also need offset >0? Check .shstrtab offset non-zero, but some sections may have offset 0? Let's filter offset==0 as well? For safety, allow offset 0? But typical sections with offset 0 are NOBITS or NULL. We'll filter offset 0 only if type is NULL? Actually .shstrtab has offset non-zero, so okay. We'll include if offset !=0 or size>0? Let's include all with type !=0,8 and size>0 regardless of offset, but original filtered out sections with offset 0? In ls, section28 offset 0x21278 non-zero, so passes. We'll just filter as above.
            displayed_sections.push(sh.clone());
            intervals.push(Interval { start: sh.sh_offset, end: sh.sh_offset+sh.sh_size, class: format!("bin_section{} section hover", sh.index), size: sh.sh_size, index: sh.index, priority: 2 });
        }
    }

    // For subranges: parse NOTE segments
    // We need to handle note parsing for NOTE segments
    #[derive(Debug, Clone)]
    struct Note {
        n_namesz: u32,
        n_descsz: u32,
        n_type: u32,
        name: Vec<u8>,
        desc: Vec<u8>,
        total_size: u64,
        offset_in_file: u64, // file offset where note starts
    }

    fn parse_notes(data: &[u8], start: usize, size: usize, little: bool) -> Vec<Note> {
        let mut notes = Vec::new();
        let mut offset = 0usize;
        while offset + 12 <= size {
            let abs_off = start + offset;
            if abs_off + 12 > data.len() { break; }
            let slice = &data[abs_off..abs_off+12];
            let (n_namesz, n_descsz, n_type) = if little {
                (u32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]),
                 u32::from_le_bytes([slice[4], slice[5], slice[6], slice[7]]),
                 u32::from_le_bytes([slice[8], slice[9], slice[10], slice[11]]))
            } else {
                (u32::from_be_bytes([slice[0], slice[1], slice[2], slice[3]]),
                 u32::from_be_bytes([slice[4], slice[5], slice[6], slice[7]]),
                 u32::from_be_bytes([slice[8], slice[9], slice[10], slice[11]]))
            };
            // Check if sizes make sense
            let namesz_aligned = ((n_namesz as usize + 3) /4)*4;
            let descsz_aligned = ((n_descsz as usize + 3)/4)*4;
            let total = 12 + namesz_aligned + descsz_aligned;
            if offset + total > size { break; }
            // Check data bounds for name and desc
            if abs_off + 12 + namesz_aligned + descsz_aligned > data.len() { break; }
            let name_start = abs_off + 12;
            let name_end = name_start + n_namesz as usize;
            let name = if name_end <= data.len() { data[name_start..name_end].to_vec() } else { Vec::new() };
            let desc_start = abs_off + 12 + namesz_aligned;
            let desc_end = desc_start + n_descsz as usize;
            let desc = if desc_end <= data.len() { data[desc_start..desc_end].to_vec() } else { Vec::new() };
            notes.push(Note { n_namesz, n_descsz, n_type, name, desc, total_size: total as u64, offset_in_file: abs_off as u64 });
            offset += total;
        }
        notes
    }

    // For each displayed NOTE segment, collect sections inside it that are NOTE type
    // We'll generate subranges
    let mut subrange_intervals: Vec<Interval> = Vec::new();
    // Keep track of which sections already have subranges to avoid duplicate
    let mut sections_with_subrange = std::collections::HashSet::new();

    // First, gather all NOTE segments (p_type ==4)
    let note_segments: Vec<Phdr> = displayed_segments.iter().filter(|ph| ph.p_type==4).cloned().collect();

    // For aggregation in info tables, we will need all notes from all NOTE segments combined
    let mut all_notes: Vec<Note> = Vec::new();
    for seg in &note_segments {
        let start = seg.p_offset as usize;
        let size = seg.p_filesz as usize;
        if start+size <= data.len() {
            let notes = parse_notes(&data, start, size, little);
            all_notes.extend(notes);
        }
    }

    // Now for bytes rendering:
    // If a NOTE segment contains NOTE sections, generate subranges inside those sections
    for seg in &note_segments {
        let mut sections_inside: Vec<Shdr> = Vec::new();
        for sec in &displayed_sections {
            if sec.sh_type==7 && sec.sh_offset >= seg.p_offset && sec.sh_offset + sec.sh_size <= seg.p_offset + seg.p_filesz {
                sections_inside.push(sec.clone());
            }
        }
        if sections_inside.is_empty() {
            // No NOTE sections inside, generate subranges directly inside segment
            let start = seg.p_offset as usize;
            let size = seg.p_filesz as usize;
            if start+size <= data.len() {
                let notes = parse_notes(&data, start, size, little);
                for note in notes {
                    subrange_intervals.push(Interval { start: note.offset_in_file, end: note.offset_in_file+note.total_size, class: "segment_subrange hover".to_string(), size: note.total_size, index: seg.index, priority: 5 });
                }
            }
        } else {
            // For each section inside, generate subranges inside section
            for sec in sections_inside {
                if sections_with_subrange.contains(&sec.index) { continue; }
                let start = sec.sh_offset as usize;
                let size = sec.sh_size as usize;
                if start+size <= data.len() {
                    let notes = parse_notes(&data, start, size, little);
                    for note in notes {
                        subrange_intervals.push(Interval { start: note.offset_in_file, end: note.offset_in_file+note.total_size, class: "segment_subrange hover".to_string(), size: note.total_size, index: sec.index, priority: 5 });
                    }
                    sections_with_subrange.insert(sec.index);
                }
            }
        }
    }

    // For sections that are NOTE but not inside any NOTE segment? Original didn't generate subrange, so skip.

    // Add subrange intervals to main intervals
    intervals.extend(subrange_intervals.clone());

    // Now we have intervals. Need to generate bytes html.

    // Sort intervals by start, then size descending, then priority ascending? Actually for same start, larger outer first, so size descending. For equal size, lower index outer first. Also priority: segments should be outer to sections, but size already handles that. However we also need to ensure ehdr outer to ident etc – size descending does that (ehdr 64 > ident 16 > magic 4). So size descending is enough, but we also have priority to break ties? We'll use (start, priority, Reverse(size), index)

    // For rendering, we need to generate events

    // Collect all unique positions where something starts or ends, up to file_size
    let mut positions: Vec<u64> = Vec::new();
    for iv in &intervals {
        positions.push(iv.start);
        positions.push(iv.end);
    }
