cat > src/main.rs <<'RS'
use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        println!("Usage: elfcat <filename>\nWrites <filename>.html to CWD.");
        std::process::exit(1);
    }
    let filename = &args[1];
    let data = match fs::read(filename) {
        Ok(d) => d,
        Err(e) => {
            println!("Failed to read file \"{}\": {}", filename, e);
            std::process::exit(1);
        }
    };

    // check size
    if data.len() < 16 {
        println!("Failed to parse ELF: file is smaller than ELF header's e_ident");
        std::process::exit(1);
    }
    // magic
    if data[0] != 0x7f || data[1] != b'E' || data[2] != b'L' || data[3] != b'F' {
        println!("Failed to parse ELF: mismatched magic: not an ELF file");
        std::process::exit(1);
    }
    let ei_class = data[4];
    if ei_class != 1 && ei_class != 2 {
        println!("Failed to parse ELF: Unknown bitness: {}", ei_class);
        std::process::exit(1);
    }
    let ei_data = data[5];
    if ei_data != 1 && ei_data != 2 {
        println!("Failed to parse ELF: Unknown endianness: {}", ei_data);
        std::process::exit(1);
    }
    // For simplicity, we will parse further; if file smaller than ehdr size, error
    let is_64 = ei_class == 2;
    let little = ei_data == 1;
    let ehdr_size = if is_64 { 64 } else { 52 };
    if data.len() < ehdr_size {
        println!("Failed to parse ELF: file is smaller than ELF file header");
        std::process::exit(1);
    }

    // Parse ehdr
    let e_type;
    let e_machine;
    let e_version;
    let e_entry: u64;
    let e_phoff: u64;
    let e_shoff: u64;
    let e_flags: u32;
    let e_ehsize: u16;
    let e_phentsize: u16;
    let e_phnum: u16;
    let e_shentsize: u16;
    let e_shnum: u16;
    let e_shstrndx: u16;

    if is_64 {
        if little {
            e_type = u16::from_le_bytes([data[16], data[17]]);
            e_machine = u16::from_le_bytes([data[18], data[19]]);
