    }
    let mut phdrs: Vec<Phdr> = Vec::new();
    for i in 0..e_phnum as usize {
        let off = e_phoff as usize + i * e_phentsize as usize;
        if off + e_phentsize as usize > data.len() {
            // original would panic, but we will break and not add more
            // To mimic panic, we would need to panic, but let's just break for valid files
            // For invalid, original panics, we will also panic to match behavior? Let's attempt to mimic panic message for phdrs?
            // For now, break
            break;
        }
        let slice = &data[off..off+e_phentsize as usize];
        let (p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align) = if is_64 {
            if little {
                let p_type = u32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]);
                let p_flags = u32::from_le_bytes([slice[4], slice[5], slice[6], slice[7]]);
