                let sh_flags = u64::from_be_bytes([slice[8], slice[9], slice[10], slice[11], slice[12], slice[13], slice[14], slice[15]]);
                let sh_addr = u64::from_be_bytes([slice[16], slice[17], slice[18], slice[19], slice[20], slice[21], slice[22], slice[23]]);
                let sh_offset = u64::from_be_bytes([slice[24], slice[25], slice[26], slice[27], slice[28], slice[29], slice[30], slice[31]]);
                let sh_size = u64::from_be_bytes([slice[32], slice[33], slice[34], slice[35], slice[36], slice[37], slice[38], slice[39]]);
                let sh_link = u32::from_be_bytes([slice[40], slice[41], slice[42], slice[43]]);
                let sh_info = u32::from_be_bytes([slice[44], slice[45], slice[46], slice[47]]);
                let sh_addralign = u64::from_be_bytes([slice[48], slice[49], slice[50], slice[51], slice[52], slice[53], slice[54], slice[55]]);
                let sh_entsize = u64::from_be_bytes([slice[56], slice[57], slice[58], slice[59], slice[60], slice[61], slice[62], slice[63]]);
                (sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size, sh_link, sh_info, sh_addralign, sh_entsize)
            }
        } else {
            if little {
                let sh_name = u32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]);
                let sh_type = u32::from_le_bytes([slice[4], slice[5], slice[6], slice[7]]);
                let sh_flags = u32::from_le_bytes([slice[8], slice[9], slice[10], slice[11]]) as u64;
                let sh_addr = u32::from_le_bytes([slice[12], slice[13], slice[14], slice[15]]) as u64;
                let sh_offset = u32::from_le_bytes([slice[16], slice[17], slice[18], slice[19]]) as u64;
                let sh_size = u32::from_le_bytes([slice[20], slice[21], slice[22], slice[23]]) as u64;
                let sh_link = u32::from_le_bytes([slice[24], slice[25], slice[26], slice[27]]);
                let sh_info = u32::from_le_bytes([slice[28], slice[29], slice[30], slice[31]]);
                let sh_addralign = u32::from_le_bytes([slice[32], slice[33], slice[34], slice[35]]) as u64;
                let sh_entsize = u32::from_le_bytes([slice[36], slice[37], slice[38], slice[39]]) as u64;
