    }

    // Get section names via shstrtab
    let mut shstrtab_data: Vec<u8> = Vec::new();
    if (e_shstrndx as usize) < shdrs.len() {
        let sh = &shdrs[e_shstrndx as usize];
        let start = sh.sh_offset as usize;
        let end = start + sh.sh_size as usize;
        if end <= data.len() {
            shstrtab_data = data[start..end].to_vec();
        }
    }
    let get_section_name = |sh_name: u32| -> String {
        if shstrtab_data.is_empty() {
            return String::new();
        }
        let off = sh_name as usize;
        if off >= shstrtab_data.len() {
            return String::new();
        }
        let mut end = off;
        while end < shstrtab_data.len() && shstrtab_data[end] != 0 {
            end += 1;
        }
        String::from_utf8_lossy(&shstrtab_data[off..end]).to_string()
    };

    // Helpers for formatting
    fn format_file_size(size: usize) -> String {
        let b = size as u64;
        if b < 1024 {
            format!("{} B", b)
        } else if b < 1024*1024 {
            let kib = b as f64 / 1024.0;
            format!("{:.1} KiB ({} B)", kib, b)
        } else if b < 1024*1024*1024 {
            let mib = b as f64 / (1024.0*1024.0);
            format!("{:.1} MiB ({} B)", mib, b)
        } else {
            let gib = b as f64 / (1024.0*1024.0*1024.0);
            format!("{:.1} GiB ({} B)", gib, b)
        }
    }
    fn format_size_human(size: u64) -> Option<String> {
        if size < 1024 {
            None
        } else if size < 1024*1024 {
            Some(format!("{:.1} KiB", size as f64 / 1024.0))
        } else if size < 1024*1024*1024 {
            Some(format!("{:.1} MiB", size as f64 / (1024.0*1024.0)))
        } else {
            Some(format!("{:.1} GiB", size as f64 / (1024.0*1024.0*1024.0)))
        }
    }
    fn format_number_hex_title_decimal(number: u64, is_hex_display: bool) -> (String, String) {
        // For fileinfo entry: title decimal, display hex
        // For others: title hex, display decimal
        // This function returns (title, display)
        if is_hex_display {
            (format!("{}", number), format!("0x{:x}", number))
        } else {
            (format!("0x{:x}", number), format!("{}", number))
        }
    }

    fn abi_string(abi: u8) -> (&'static str, &'static str) {
        // returns (label, name)
        // label is "ABI" for SysV else "Uncommon ABI(!)"
        match abi {
            0 => ("ABI", "SysV"),
            1 => ("Uncommon ABI(!)", "HP-UX"),
            2 => ("Uncommon ABI(!)", "NetBSD"),
            3 => ("Uncommon ABI(!)", "Linux"),
            4 => ("Uncommon ABI(!)", "Hurd"),
            6 => ("Uncommon ABI(!)", "Solaris"),
            7 => ("Uncommon ABI(!)", "AIX"),
            8 => ("Uncommon ABI(!)", "IRIX"),
            9 => ("Uncommon ABI(!)", "FreeBSD"),
            10 => ("Uncommon ABI(!)", "Tru64"),
            11 => ("Uncommon ABI(!)", "Modesto"),
            12 => ("Uncommon ABI(!)", "OpenBSD"),
            13 => ("Uncommon ABI(!)", "OpenVMS"),
            64 => ("Uncommon ABI(!)", "ARM"),
            97 => ("Uncommon ABI(!)", "ARM"),
            255 => ("Uncommon ABI(!)", "Standalone"),
            _ => ("Uncommon ABI(!)", ""), // will handle unknown
        }
    }
