}\n\n      function pushArrowElems() {\n          arrows.innerHTML = batchElems;\n      }\n\n      function redrawArrows() {\n          clearArrows();\n\n          for (let i = 0; i < connections.length; ++i) {\n              let conn = connections[i];\n\n              addSvgArrow(conn[0], conn[1]);\n          }\n\n          pushArrowElems();\n      }\n\n      window.onresize = function() {\n          redrawArrows();\n      }\n\n");
